import subprocess
import platform
import time
def task_func(url):
    system = platform.system()
    if system == "Windows":
        process = subprocess.Popen(['cmd', '/c', 'start', url])
    elif system == "Darwin":
        process = subprocess.Popen(['open', url])
    else:
        process = subprocess.Popen(['xdg-open', url])

    return code if (code := process.wait()) is not None else 0

